#include "transfer.hpp"
#include <algorithm>
#include <cmath>
#include <cstring>
#include <stdexcept>

namespace etch {
namespace {
constexpr uint8_t Magic[]{0x45,0x54,0x43,0x48};
uint32_t crc32(const uint8_t* p,std::size_t n){uint32_t c=0xffffffffu;for(std::size_t i=0;i<n;i++){c^=p[i];for(int j=0;j<8;j++)c=(c>>1)^((c&1)?0xedb88320u:0u);}return c^0xffffffffu;}
void u16(std::vector<uint8_t>& a,uint16_t v){a.push_back(v&255);a.push_back((v>>8)&255);}
uint16_t readU16(const std::vector<uint8_t>& a,std::size_t& o){if(o+2>a.size())throw std::runtime_error("Truncated patch payload");const auto v=uint16_t(a[o])|(uint16_t(a[o+1])<<8);o+=2;return v;}
void u32(std::vector<uint8_t>& a,uint32_t v){a.push_back(v&255);a.push_back((v>>8)&255);a.push_back((v>>16)&255);a.push_back((v>>24)&255);}
uint32_t readU32(const std::vector<uint8_t>& a,std::size_t o){return uint32_t(a[o])|(uint32_t(a[o+1])<<8)|(uint32_t(a[o+2])<<16)|(uint32_t(a[o+3])<<24);}
void i16(std::vector<uint8_t>& a,int16_t v){const auto x=static_cast<uint16_t>(v);a.push_back(x&255);a.push_back((x>>8)&255);}
int16_t readI16(const std::vector<uint8_t>& a,std::size_t o){return static_cast<int16_t>(uint16_t(a[o])|(uint16_t(a[o+1])<<8));}
void f32(std::vector<uint8_t>& a,float v){static_assert(sizeof(float)==4,"ETCH transfer requires IEEE-size float");uint32_t x=0;std::memcpy(&x,&v,4);u32(a,x);}
float readF32(const std::vector<uint8_t>& a,std::size_t& o){if(o+4>a.size())throw std::runtime_error("Truncated patch payload");const auto x=readU32(a,o);o+=4;float v=0;std::memcpy(&v,&x,4);return v;}
uint8_t readU8(const std::vector<uint8_t>& a,std::size_t& o){if(o>=a.size())throw std::runtime_error("Truncated patch payload");return a[o++];}
bool validName(const std::string& s){return !s.empty()&&s.size()<=12&&std::all_of(s.begin(),s.end(),[](unsigned char c){return c>=0x20&&c<=0x7e;});}
void name(std::vector<uint8_t>& a,const std::string& s){if(!validName(s))throw std::invalid_argument("Invalid transfer name");a.push_back(static_cast<uint8_t>(s.size()));a.insert(a.end(),s.begin(),s.end());}
std::string readName(const std::vector<uint8_t>& a,std::size_t& o){if(o>=a.size())throw std::runtime_error("Invalid transfer name");const auto n=a[o++];if(n<1||n>12||o+n>a.size())throw std::runtime_error("Invalid transfer name");std::string s;for(uint8_t i=0;i<n;i++){const auto c=a[o++];if(c<0x20||c>0x7e)throw std::runtime_error("Invalid transfer name");s.push_back(static_cast<char>(c));}return s;}
bool bound(float v,float lo,float hi){return std::isfinite(v)&&v>=lo&&v<=hi;}
bool valid(const Params& p){return bound(p.morph,0,1)&&bound(p.depth,0,1)&&bound(p.ratio,.125f,16)&&bound(p.freeHz,.05f,2000)&&bound(p.bpm,30,300)&&bound(p.bars,1.f/64,8)&&bound(p.attack,.001f,4)&&bound(p.decay,.001f,4)&&bound(p.sustain,0,1)&&bound(p.release,.005f,5)&&bound(p.fAttack,.001f,4)&&bound(p.fDecay,.001f,4)&&bound(p.fSustain,0,1)&&bound(p.fRelease,.005f,5)&&bound(p.filterEnv,-1,1)&&bound(p.gain,0,1)&&bound(p.phaseA,0,359)&&bound(p.phaseB,0,359)&&bound(p.invertA,0,1)&&bound(p.invertB,0,1)&&bound(p.cutoff,20,18000)&&bound(p.resonance,0,1)&&bound(p.drive,0,1)&&bound(p.chorus,0,1)&&bound(p.delay,0,1)&&bound(p.reverb,0,1)&&bound(p.glide,0,2)&&bound(p.bendRange,1,12)&&bound(p.velSense,0,1)&&(p.invertA==0||p.invertA==1)&&(p.invertB==0||p.invertB==1);}
bool validLocks(const StepLocks& l){return (!l.hasMorph||bound(l.morph,0,1))&&(!l.hasDepth||bound(l.depth,0,1))&&(!l.hasCutoff||bound(l.cutoff,20,18000))&&(!l.hasChorus||bound(l.chorus,0,1))&&(!l.hasDelay||bound(l.delay,0,1))&&(!l.hasReverb||bound(l.reverb,0,1));}
bool validPerformance(const PerformanceData& p){
 if(p.arpMode>ArpMode::Random||p.arpRate>StepRate::ThirtySecond||p.arpOctaves<1||p.arpOctaves>4||!bound(p.arpGate,.05f,1))return false;
 if(!validHarmony(p.harmony))return false;
 if((p.seqLength!=8&&p.seqLength!=16&&p.seqLength!=32&&p.seqLength!=64&&p.seqLength!=128&&p.seqLength!=256)||p.seqRate>StepRate::ThirtySecond||!bound(p.seqSwing,0,.75f)||!bound(p.seqGate,.05f,1))return false;
 return std::all_of(p.steps.begin(),p.steps.end(),[](const SequenceStep& s){
  if(s.noteCount>MaxStepNotes||!validLocks(s.locks))return false;
  std::array<bool,128> seen{};
  for(std::size_t i=0;i<s.noteCount;i++){const auto& n=s.notes[i];if(n.note>127||!bound(n.velocity,0,1)||n.length<1||n.length>256||seen[n.note])return false;seen[n.note]=true;}
  return true;
 });
}
std::vector<uint8_t> frame(TransferKind kind,uint8_t slot,const std::vector<uint8_t>& payload){auto raw=payload;u32(raw,crc32(payload.data(),payload.size()));const auto packed=pack7(raw);std::vector<uint8_t> d{0xf0,EtchSysExManufacturer,Magic[0],Magic[1],Magic[2],Magic[3],EtchTransferProtocol,static_cast<uint8_t>(kind),slot};d.insert(d.end(),packed.begin(),packed.end());d.push_back(0xf7);return d;}
struct Frame {TransferKind kind;uint8_t slot;std::vector<uint8_t> body;};
Frame unframe(const std::vector<uint8_t>& d){if(d.size()<14||d.front()!=0xf0||d.back()!=0xf7)throw std::runtime_error("Not a complete SysEx message");if(d[1]!=EtchSysExManufacturer||!std::equal(std::begin(Magic),std::end(Magic),d.begin()+2))throw std::runtime_error("Not an ETCH transfer");if(d[6]!=EtchTransferProtocol)throw std::runtime_error("Unsupported ETCH transfer protocol");if(d[7]!=1&&d[7]!=2)throw std::runtime_error("Unknown ETCH transfer type");auto raw=unpack7(std::vector<uint8_t>(d.begin()+9,d.end()-1));if(raw.size()<5)throw std::runtime_error("Transfer payload too short");const auto stored=readU32(raw,raw.size()-4);raw.resize(raw.size()-4);if(stored!=crc32(raw.data(),raw.size()))throw std::runtime_error("Transfer CRC mismatch");return {static_cast<TransferKind>(d[7]),d[8],std::move(raw)};}
uint8_t lockMask(const StepLocks& l){return static_cast<uint8_t>((l.hasMorph?1:0)|(l.hasDepth?2:0)|(l.hasCutoff?4:0)|(l.hasChorus?8:0)|(l.hasDelay?16:0)|(l.hasReverb?32:0));}
void appendLocks(std::vector<uint8_t>& b,const StepLocks& l){const auto mask=lockMask(l);b.push_back(mask);if(mask&1)f32(b,l.morph);if(mask&2)f32(b,l.depth);if(mask&4)f32(b,l.cutoff);if(mask&8)f32(b,l.chorus);if(mask&16)f32(b,l.delay);if(mask&32)f32(b,l.reverb);}
StepLocks readLocks(const std::vector<uint8_t>& b,std::size_t& o){StepLocks l;const auto mask=readU8(b,o);if(mask&0xc0)throw std::runtime_error("Invalid sequence lock mask");if(mask&1){l.hasMorph=true;l.morph=readF32(b,o);}if(mask&2){l.hasDepth=true;l.depth=readF32(b,o);}if(mask&4){l.hasCutoff=true;l.cutoff=readF32(b,o);}if(mask&8){l.hasChorus=true;l.chorus=readF32(b,o);}if(mask&16){l.hasDelay=true;l.delay=readF32(b,o);}if(mask&32){l.hasReverb=true;l.reverb=readF32(b,o);}if(!validLocks(l))throw std::runtime_error("Invalid sequence lock");return l;}
}

std::vector<uint8_t> pack7(const std::vector<uint8_t>& raw){std::vector<uint8_t> out;out.reserve((raw.size()*8+6)/7);for(std::size_t i=0;i<raw.size();i+=7){const auto n=std::min<std::size_t>(7,raw.size()-i),h=out.size();out.push_back(0);uint8_t head=0;for(std::size_t j=0;j<n;j++){if(raw[i+j]&0x80)head|=uint8_t(1u<<j);out.push_back(raw[i+j]&0x7f);}out[h]=head;}return out;}
std::vector<uint8_t> unpack7(const std::vector<uint8_t>& packed){std::vector<uint8_t> out;for(std::size_t i=0;i<packed.size();){const auto head=packed[i++];if(head&0x80)throw std::runtime_error("Invalid 7-bit packet");const auto n=std::min<std::size_t>(7,packed.size()-i);if(!n)throw std::runtime_error("Truncated 7-bit packet");for(std::size_t j=0;j<n;j++){const auto b=packed[i++];if(b&0x80)throw std::runtime_error("Invalid SysEx data byte");out.push_back(uint8_t(b|(((head>>j)&1)<<7)));}}return out;}
std::vector<uint8_t> encodeWaveSysex(uint8_t slot,const WaveTransfer& wave){if(slot>=64)throw std::invalid_argument("Wave slot out of range");if(!validWaveFx(wave.fx))throw std::invalid_argument("Invalid wave FX");std::vector<uint8_t> p{2};name(p,wave.name);for(auto x:wave.points)i16(p,x);f32(p,wave.fx.drive);f32(p,wave.fx.bitcrush);f32(p,wave.fx.chorus);f32(p,wave.fx.delay);f32(p,wave.fx.reverb);f32(p,wave.fx.fold);f32(p,wave.fx.smooth);f32(p,wave.fx.mix);return frame(TransferKind::Wave,slot,p);}
std::vector<uint8_t> encodePatchSysex(uint8_t slot,const PatchTransfer& patch){
 if(slot>=32)throw std::invalid_argument("Patch slot out of range");
 if(!validName(patch.name)||std::any_of(patch.slots.begin(),patch.slots.end(),[](uint8_t s){return s>=64;})||!valid(patch.params)||!validPerformance(patch.performance))throw std::invalid_argument("Invalid patch transfer");
 const auto& p=patch.params;const auto& perf=patch.performance;std::vector<uint8_t> b{8};name(b,patch.name);b.insert(b.end(),patch.slots.begin(),patch.slots.end());f32(b,p.morph);f32(b,p.depth);f32(b,p.ratio);b.push_back(static_cast<uint8_t>(p.mode));b.push_back(static_cast<uint8_t>(p.target));b.push_back(static_cast<uint8_t>(p.curve));f32(b,p.freeHz);f32(b,p.bpm);f32(b,p.bars);f32(b,p.attack);f32(b,p.decay);f32(b,p.sustain);f32(b,p.release);f32(b,p.fAttack);f32(b,p.fDecay);f32(b,p.fSustain);f32(b,p.fRelease);f32(b,p.filterEnv);f32(b,p.gain);f32(b,p.phaseA);f32(b,p.phaseB);b.push_back(static_cast<uint8_t>(p.invertA));b.push_back(static_cast<uint8_t>(p.invertB));b.push_back(static_cast<uint8_t>(p.filter));f32(b,p.cutoff);f32(b,p.resonance);f32(b,p.drive);f32(b,p.chorus);f32(b,p.delay);f32(b,p.reverb);b.push_back(static_cast<uint8_t>(p.voice));f32(b,p.glide);f32(b,p.bendRange);f32(b,p.velSense);
 b.push_back(static_cast<uint8_t>(perf.arpMode));b.push_back(static_cast<uint8_t>(perf.arpRate));b.push_back(perf.arpOctaves);f32(b,perf.arpGate);u16(b,perf.seqLength);b.push_back(static_cast<uint8_t>(perf.seqRate));f32(b,perf.seqSwing);f32(b,perf.seqGate);
 b.push_back(perf.harmony.root);b.push_back(static_cast<uint8_t>(perf.harmony.mode));b.push_back(static_cast<uint8_t>(perf.harmony.keyLock));b.push_back(static_cast<uint8_t>(perf.harmony.chord));
 for(const auto& step:perf.steps){b.push_back(step.noteCount);for(std::size_t i=0;i<step.noteCount;i++){const auto& n=step.notes[i];b.push_back(n.note);b.push_back(static_cast<uint8_t>(std::lround(std::clamp(n.velocity,0.f,1.f)*127)));u16(b,n.length);}appendLocks(b,step.locks);}return frame(TransferKind::Patch,slot,b);
}
DecodedTransfer decodeEtchSysex(const std::vector<uint8_t>& data){
 const auto f=unframe(data);std::size_t o=0;if(f.body.empty())throw std::runtime_error("Transfer payload too short");const auto payloadVersion=f.body[o++];if(payloadVersion<1||payloadVersion>8)throw std::runtime_error("Unsupported object payload version");DecodedTransfer r;r.kind=f.kind;r.slot=f.slot;
 if(f.kind==TransferKind::Wave){if(f.slot>=64)throw std::runtime_error("Wave slot out of range");if(payloadVersion!=1&&payloadVersion!=2)throw std::runtime_error("Unsupported wave payload version");r.wave.name=readName(f.body,o);if(f.body.size()-o<256)throw std::runtime_error("Invalid wave payload length");for(auto& x:r.wave.points){x=readI16(f.body,o);o+=2;}if(payloadVersion>=2){r.wave.fx.drive=readF32(f.body,o);r.wave.fx.bitcrush=readF32(f.body,o);r.wave.fx.chorus=readF32(f.body,o);r.wave.fx.delay=readF32(f.body,o);r.wave.fx.reverb=readF32(f.body,o);r.wave.fx.fold=readF32(f.body,o);r.wave.fx.smooth=readF32(f.body,o);r.wave.fx.mix=readF32(f.body,o);if(!validWaveFx(r.wave.fx))throw std::runtime_error("Invalid wave FX payload");}if(o!=f.body.size())throw std::runtime_error("Unexpected wave payload data");return r;}
 if(f.slot>=32)throw std::runtime_error("Patch slot out of range");
 r.patch.name=readName(f.body,o);if(o+3>f.body.size())throw std::runtime_error("Truncated patch payload");for(auto& x:r.patch.slots){x=f.body[o++];if(x>=64)throw std::runtime_error("Patch wave slot out of range");}
 auto& p=r.patch.params;p.morph=readF32(f.body,o);p.depth=readF32(f.body,o);p.ratio=readF32(f.body,o);if(o+3>f.body.size())throw std::runtime_error("Truncated patch payload");p.mode=static_cast<Mode>(f.body[o++]);p.target=static_cast<Target>(f.body[o++]);p.curve=static_cast<Curve>(f.body[o++]);if(p.mode>Mode::Tempo||p.target>Target::Morph||p.curve>Curve::Hard)throw std::runtime_error("Invalid patch enum");p.freeHz=readF32(f.body,o);p.bpm=readF32(f.body,o);p.bars=readF32(f.body,o);p.attack=readF32(f.body,o);p.decay=readF32(f.body,o);p.sustain=readF32(f.body,o);p.release=readF32(f.body,o);if(payloadVersion>=2){p.fAttack=readF32(f.body,o);p.fDecay=readF32(f.body,o);p.fSustain=readF32(f.body,o);p.fRelease=readF32(f.body,o);p.filterEnv=readF32(f.body,o);}p.gain=readF32(f.body,o);p.phaseA=readF32(f.body,o);p.phaseB=readF32(f.body,o);if(o+3>f.body.size())throw std::runtime_error("Truncated patch payload");p.invertA=f.body[o++];p.invertB=f.body[o++];p.filter=static_cast<Filter>(f.body[o++]);if(p.filter>Filter::HP)throw std::runtime_error("Invalid filter enum");p.cutoff=readF32(f.body,o);p.resonance=readF32(f.body,o);p.drive=readF32(f.body,o);if(payloadVersion>=3){p.chorus=readF32(f.body,o);p.delay=readF32(f.body,o);p.reverb=readF32(f.body,o);}if(o>=f.body.size())throw std::runtime_error("Truncated patch payload");p.voice=static_cast<VoiceMode>(f.body[o++]);if(p.voice>VoiceMode::Mono)throw std::runtime_error("Invalid voice enum");p.glide=readF32(f.body,o);p.bendRange=readF32(f.body,o);p.velSense=readF32(f.body,o);
 if(payloadVersion>=4){auto& perf=r.patch.performance;perf.arpMode=static_cast<ArpMode>(readU8(f.body,o));perf.arpRate=static_cast<StepRate>(readU8(f.body,o));perf.arpOctaves=readU8(f.body,o);perf.arpGate=readF32(f.body,o);perf.seqLength=payloadVersion>=8?readU16(f.body,o):readU8(f.body,o);perf.seqRate=static_cast<StepRate>(readU8(f.body,o));perf.seqSwing=readF32(f.body,o);perf.seqGate=readF32(f.body,o);if(payloadVersion>=6){perf.harmony.root=readU8(f.body,o);perf.harmony.mode=static_cast<ScaleMode>(readU8(f.body,o));perf.harmony.keyLock=static_cast<KeyLockMode>(readU8(f.body,o));perf.harmony.chord=static_cast<ChordMode>(readU8(f.body,o));if(!validHarmony(perf.harmony))throw std::runtime_error("Invalid harmony config");}const std::size_t storedSteps=payloadVersion>=8?perf.steps.size():64;for(std::size_t si=0;si<storedSteps;si++){auto& step=perf.steps[si];if(payloadVersion>=5){step.noteCount=readU8(f.body,o);if(step.noteCount>MaxStepNotes)throw std::runtime_error("Invalid sequence chord size");for(std::size_t i=0;i<step.noteCount;i++){step.notes[i].note=readU8(f.body,o);step.notes[i].velocity=readU8(f.body,o)/127.f;step.notes[i].length=payloadVersion>=8?readU16(f.body,o):payloadVersion>=7?readU8(f.body,o):1;}}else{const auto rawNote=readU8(f.body,o),rawVelocity=readU8(f.body,o);if(rawNote!=255){step.noteCount=1;step.notes[0].note=rawNote;step.notes[0].velocity=rawVelocity/127.f;step.notes[0].length=1;}}step.locks=readLocks(f.body,o);}if(!validPerformance(perf))throw std::runtime_error("Invalid performance payload");}
 if(o!=f.body.size()||!valid(p))throw std::runtime_error("Invalid patch payload");
 return r;
}
}
